SELECT count() AS mismatches FROM (SELECT field_name,value,author_key,doc_id,version,sum(weight) AS delta FROM (SELECT field_name,value,author_key,doc_id,version,toInt8(1) AS weight FROM (SELECT * FROM timestamps) UNION ALL SELECT field_name,value,author_key,doc_id,version,toInt8(-1) AS weight FROM (SELECT 'posts' AS field_name,created_at AS value,author_key,doc_id,updated_at AS version FROM documents FINAL WHERE deleted=0 AND collection_name='posts' AND NOT has(tags,'ad') AND NOT has(tags,'product'))) GROUP BY field_name,value,author_key,doc_id,version HAVING delta!=0)
